command:
// Conspiracy Board: Change Drawing Author
// Reassign the author of every drawing on the current scene to a user of your
// choosing (GMs included). GM only. Requires the Conspiracy Board module.
//
// "Author" is descriptive metadata, not a permission: reassigning it does not
// grant the new author edit rights, and it does not take any away from the old
// one. Foundry forms the author id at document creation as `user.id.slice(0, 16)`,
// with runs from the setup screen forming it as `user.id`; both forms are listed
// below so documents from either path are recognised.

const MOD = "conspiracy-board";

const scene = canvas.scene;
if (!scene) return ui.notifications.warn("No scene is currently viewed.");
if (!game.user.isGM) return ui.notifications.warn("Only a GM can reassign drawing authors.");

const users = game.users.contents
  .filter((u) => u.active || u.isGM)
  .sort((a, b) => Number(a.isGM) - Number(b.isGM) || a.name.localeCompare(b.name));
if (!users.length) return ui.notifications.warn("No users found in this world.");

const drawings = scene.drawings.contents;
if (!drawings.length) return ui.notifications.warn(`No drawings on "${scene.name}".`);

/** Foundry's canonical form of a user id as an author. */
const shortId = (id) => String(id ?? "").slice(0, 16);

/** Who authored a drawing, allowing for the legacy ids made from the setup screen. */
function authorOf(doc) {
  const raw = String(doc.author ?? "");
  for (const u of game.users) {
    if (raw === u.id || raw === shortId(u.id)) return u;
  }
  return null;
}

// v14: drawings carry a name and belong to a Scene Level.
const levels = scene.levels?.contents ?? [];
const levelName = (id) => levels.find((l) => l.id === id)?.name ?? "Unknown level";

const options = users
  .map((u) => `<option value="${u.id}">${u.name}${u.isGM ? " (GM)" : ""}</option>`)
  .join("");

const byLevel = new Map();
for (const d of drawings) {
  const key = d.level ?? "no-level";
  byLevel.set(key, (byLevel.get(key) ?? 0) + 1);
}
const levelSummary = [...byLevel.entries()]
  .map(([id, n]) => `<li>${levelName(id)}: ${n} drawing(s)</li>`)
  .join("");

const preview = drawings.slice(0, 8).map((d) => {
  const who = authorOf(d)?.name ?? (d.author ? "unknown or deleted user" : "none");
  return `<li><em>${d.name || "(unnamed)"}</em> — ${who}</li>`;
}).join("");

const cards = drawings.filter((d) => d.getFlag(MOD, "card")).length;
const cardNote = cards
  ? `<p class="notes">${cards} of these are Conspiracy Board clues or pins.</p>`
  : "";

const authorId = await foundry.applications.api.DialogV2.wait({
  window: { title: "Change Drawing Author" },
  content: `
    <form>
      <div class="form-group">
        <label>New author</label>
        <div class="form-fields"><select name="authorId">${options}</select></div>
      </div>
      <div class="form-group">
        <label>Scope</label>
        <div class="form-fields">
          <span>${drawings.length} drawing(s) on <strong>${scene.name}</strong></span>
        </div>
      </div>
      ${cardNote}
      <p class="notes"><strong>By Scene Level</strong></p>
      <ul class="notes">${levelSummary}</ul>
      <p class="notes"><strong>Current authors (first ${Math.min(8, drawings.length)})</strong></p>
      <ul class="notes">${preview}</ul>
    </form>`,
  buttons: [
    {
      action: "apply",
      label: "Reassign",
      default: true,
      callback: (event, button) => button.form.elements.authorId.value
    }
  ],
  rejectClose: false,
  modal: true
});

if (!authorId) return;
const target = game.users.get(authorId);
if (!target) return ui.notifications.error("That user no longer exists.");

const newAuthor = shortId(target.id);
const updates = drawings
  .filter((d) => String(d.author ?? "") !== newAuthor)
  .map((d) => ({ _id: d.id, author: newAuthor }));

if (!updates.length) return ui.notifications.info("Every drawing already has that author.");

await scene.updateEmbeddedDocuments("Drawing", updates, { diff: false });
ui.notifications.info(
  `Reassigned ${updates.length} drawing(s) to ${target.name}${target.isGM ? " (GM)" : ""}.`
);
